<script setup>
import {ref,onMounted,computed} from 'vue';
import {state,t,go,api,list,date,admin,human,testTypeCodes,testTypeName,testTypeCode,testDuration} from '../store';
import Icon from './Icon.vue';
import DashboardAnalytics from './DashboardAnalytics.vue';
import TestTypeCards from './TestTypeCards.vue';
import UserAvatar from './UserAvatar.vue';
const data=ref({}),loading=ref(true),error=ref('');
const stats=computed(()=>data.value.stats||data.value.statistics||data.value);
const recent=computed(()=>list(data.value.recent_attempts||data.value.recent_results||data.value.recent_activity).filter(r=>admin.value||testTypeCode(r)===filters.value.test_type));
const packages=computed(()=>list(data.value.packages||state.packages).filter(p=>admin.value||testTypeCode(p)===filters.value.test_type).slice(0,3));
const firstName=computed(()=>state.user?.name?.split(' ')[0]||'');
const metrics=computed(()=>admin.value?[['UsersRound','Participants',stats.value.participants??stats.value.total_participants??0,'blue'],['LibraryBig','Questions',stats.value.questions??stats.value.total_questions??0,'purple'],['Layers','Published assessments',stats.value.active_packages??stats.value.total_packages??state.packages.length,'cyan'],['ClipboardCheck','Pending reviews',stats.value.pending_reviews??0,'amber']]:[['BookOpenCheck',t('attempts'),stats.value.attempts??stats.value.total_attempts??0,'blue'],['ChartNoAxesCombined',t('score'),stats.value.best_score!==undefined?stats.value.best_score+' / '+(stats.value.aggregate_score_max??100):stats.value.latest_score??'—','purple'],['Award',t('level'),stats.value.level??stats.value.current_level??'—','cyan'],filters.value.test_type==='certification'?['BadgeCheck',t('certificates'),stats.value.certificates??stats.value.total_certificates??0,'amber']:['Shapes',t('competencies'),state.competencies.length,'cyan']]);
const filters=ref({date_from:'',date_to:'',package_id:'',test_type:admin.value?'':'certification'});
const typePackages=computed(()=>state.packages.filter(p=>!filters.value.test_type||testTypeCode(p)===filters.value.test_type));
async function selectType(code){filters.value.test_type=code;filters.value.package_id='';await load()}
const reportUrl=computed(()=>'/api/admin/reports?'+new URLSearchParams(Object.entries(filters.value).filter(([,v])=>v)));
let loadRevision=0;
async function load(){const revision=++loadRevision;loading.value=true;error.value='';try{const query=new URLSearchParams(Object.entries(filters.value).filter(([,value])=>value));const response=await api('/dashboard?'+query);if(revision===loadRevision)data.value=response}catch(e){if(revision===loadRevision)error.value=e.message}finally{if(revision===loadRevision)loading.value=false}}
onMounted(load);
const skillIcons=['Headphones','BookOpenText','PenLine','Mic','MessagesSquare','SpellCheck'];
</script>
<template>
<section class="dashboard-page" :aria-busy="loading">
<div class="page-heading"><div :class="{'participant-dashboard-heading':!admin}"><a v-if="!admin" href="/profile" class="dashboard-profile-avatar" :aria-label="t('profile')" @click.prevent="go('/profile')"><UserAvatar :size="56"/></a><div class="eyebrow"><span></span>{{admin?'YOUR ASSESSMENT WORKSPACE':t('journey')}}</div><h1>{{t('welcomeBack')}}, {{firstName}} <span class="wave">✦</span></h1><p>{{admin?'Everything you need to deliver meaningful language assessments.':t('overviewSub')}}</p></div><div class="date-label"><Icon name="CalendarDays" :size="17"/>{{date(new Date())}}</div></div>
<div v-if="error" class="inline-error" role="alert"><span>{{error}}</span><button class="text-button" :disabled="loading" @click="load">{{state.language==='id'?'Coba lagi':'Try again'}}<Icon name="RefreshCw" :size="18"/></button></div>
<TestTypeCards v-if="!admin" :packages="state.packages" :selected="filters.test_type"/><div v-if="!admin" class="type-history-heading"><h2>{{t(filters.test_type+'History')}}</h2><p>{{t('typeResultNote')}}</p><button class="text-button" @click="go('/tests?test_type='+filters.test_type)">{{t('browse')}}<Icon name="ArrowRight" :size="18"/></button></div>
<form class="dashboard-filters" @submit.prevent="load"><label>{{t('testType')}}<select v-model="filters.test_type" @change="filters.package_id='';load()"><option v-if="admin" value="">{{t('allTypes')}}</option><option v-for="code in testTypeCodes" :key="code" :value="code">{{testTypeName(code)}}</option></select></label><label>{{state.language==='id'?'Dari':'From'}}<input v-model="filters.date_from" type="date"></label><label>{{state.language==='id'?'Sampai':'Until'}}<input v-model="filters.date_to" type="date" :min="filters.date_from"></label><label>{{state.language==='id'?'Paket ujian':'Assessment'}}<select v-model="filters.package_id"><option value="">{{state.language==='id'?'Semua paket':'All assessments'}}</option><option v-for="p in typePackages" :value="p.id" :key="p.id">{{p.name}}</option></select></label><button class="button secondary small" :disabled="loading">{{state.language==='id'?'Terapkan':'Apply'}}</button><a v-if="admin" class="button secondary small" :href="reportUrl"><Icon name="Download" :size="15"/>CSV</a></form>

<section class="welcome-banner"><div class="banner-copy"><span class="banner-label"><span></span>{{admin?'BUILT FOR BETTER ASSESSMENT':t('learn')}}</span><h2>{{admin?'A world of potential.\nOne assessment at a time.':t('welcome')}}</h2><p>{{admin?'Create purposeful tests, follow participant progress, and turn language skills into opportunity.':'Every word brings you closer. Discover your strengths and take the next step in your Indonesian journey.'}}</p><button class="button white" @click="go(admin?'/admin/packages':'/tests')">{{admin?'Manage assessments':t('browse')}}<Icon name="ArrowUpRight" :size="17"/></button></div><img class="journey-art" src="/brand/journey.svg" alt="An open book with a speech bubble and achievement mark"><div class="banner-orbit orbit-one"></div><div class="banner-orbit orbit-two"></div></section>
<section class="metric-grid"><div v-for="m in metrics" :key="m[1]" class="metric-card"><div class="metric-top"><span class="metric-icon" :class="m[3]"><Icon :name="m[0]" :size="21"/></span><Icon name="ArrowUpRight" class="muted" :size="17"/></div><span class="metric-value" :class="{'metric-value-text':String(m[2]).length>7}">{{loading?'…':m[2]}}</span><span class="metric-label">{{m[1]}}</span><div class="metric-foot"><span class="tiny-dot" :class="m[3]"></span>{{admin?'Live platform data':m[1]===t('score')?'Your best achievement so far':'Your personal learning journey'}}</div></div></section>
<DashboardAnalytics :trend="data.trend||[]" :scores="data.competency_scores||[]" :distribution="data.level_distribution||[]"/><section class="dashboard-grid"><div class="panel proficiency-panel"><div class="panel-heading"><div><h3>{{admin?'Competency framework':'Explore your language skills'}}</h3><p>{{admin?'Dynamic skills that shape every assessment.':'A balanced approach to communicating with confidence.'}}</p></div><span class="subtle-icon"><Icon name="ChartNoAxesCombined"/></span></div><div class="skill-grid"><div v-for="(skill,i) in state.competencies" :key="skill.id" class="skill-item"><span class="skill-icon" :style="{'--skill-color':skill.color||['#5278ea','#22a7b2','#9471d5','#dc9861','#5b92c7','#69a481'][i%6]}"><Icon :name="skillIcons[i%6]" :size="19"/></span><div><strong>{{state.language==='en'?(skill.name_en||skill.name):skill.name}}</strong><small>{{skill.code?.toUpperCase()}}</small></div><Icon name="Check" :size="14" class="muted"/></div></div><div v-if="!state.competencies.length" class="empty-small">No active competencies yet.</div><div class="panel-note"><Icon name="Lightbulb" :size="16"/><span>{{admin?'Tailor competencies, weights, and levels to your institution.':'Small, consistent steps make a meaningful difference.'}}</span></div></div><div class="progress-invite"><span class="invite-icon"><Icon name="Compass" :size="28"/></span><span class="eyebrow">{{admin?'YOUR NEXT STEP':'KEEP YOUR CURIOSITY'}}</span><h3>{{admin?'Build something meaningful.':'Progress begins with possibility.'}}</h3><p>{{admin?'Design an assessment around the skills that matter to your participants.':'An assessment is more than a score. It is a clearer view of what you can do next.'}}</p><button class="text-button" @click="go(admin?'/admin/questions':'/tests')">{{admin?'Explore question bank':'Find your assessment'}}<Icon name="ArrowRight" :size="17"/></button><div class="invite-decoration">✳</div></div></section>
<section class="section-block"><div class="section-heading"><div><h2>{{admin?'Available assessment packages':t('recommended')}}</h2><p>{{t('recommendedSub')}}</p></div><button class="text-button" @click="go(admin?'/admin/packages':'/tests')">{{t('viewAll')}}<Icon name="ArrowRight" :size="17"/></button></div><div class="package-grid"><article v-for="(p,i) in packages" :key="p.id" class="package-card"><div class="package-top"><span class="package-icon" :class="['blue','cyan','purple'][i%3]"><Icon :name="['BookOpen','GraduationCap','BriefcaseBusiness'][i%3]" :size="25"/></span><span class="badge" :class="p.published?'green':'neutral'">{{p.published?t('published'):t('draft')}}</span></div><span class="badge neutral">{{testTypeName(testTypeCode(p))}}</span><h3>{{p.name}}</h3><p>{{p.description||'Build confidence in your Indonesian communication skills.'}}</p><div class="package-meta"><span><Icon name="Clock3" :size="15"/>{{testDuration(p)}}</span><span><Icon name="Shapes" :size="15"/>{{p.sections_count??p.sections?.length??state.competencies.length}} {{t('skills')}}</span></div><button class="button secondary full" @click="go(admin?'/admin/packages':'/tests/'+p.id)">{{t('view')}}<Icon name="ArrowUpRight" :size="16"/></button></article><div v-if="!packages.length" class="panel empty-state"><Icon name="BookOpen" :size="32"/><h3>{{t('empty')}}</h3><p>{{admin?'Create your first assessment package to get started.':'New assessments will appear here when published.'}}</p><button v-if="admin" class="button" @click="go('/admin/packages')">{{t('create')}}</button></div></div></section>
<section class="panel activity-panel"><div class="panel-heading"><div><h3>{{t('recent')}}</h3><p>{{t('recentSub')}}</p></div><button class="text-button" @click="go(admin?'/admin/participants':'/results?test_type='+filters.test_type)">{{t('viewAll')}}<Icon name="ArrowRight" :size="16"/></button></div><div class="table-scroll" tabindex="0" role="region" :aria-label="t('recent')"><table><thead><tr><th>Assessment</th><th>Date</th><th>{{t('status')}}</th><th>{{t('score')}}</th><th></th></tr></thead><tbody><tr v-for="r in recent" :key="r.id"><td><span class="table-title"><span class="table-file"><Icon name="FileCheck2" :size="19"/></span>{{r.package?.name||r.package_name||r.name||'Assessment'}}</span></td><td>{{date(r.submitted_at||r.created_at)}}</td><td><span class="badge" :class="r.status==='completed'?'green':'amber'">{{human(r.status)}}</span></td><td class="table-score">{{r.score??'—'}}</td><td><button class="icon-button" @click="go(r.status==='in_progress'?'/exam/'+r.id:'/results/'+r.id)" :aria-label="t('view')"><Icon name="ArrowUpRight" :size="18"/></button></td></tr><tr v-if="!recent.length"><td colspan="5"><div class="table-empty"><Icon name="Leaf" :size="27"/><span>{{admin?'Participant assessments will appear here.':t('noResults')}}</span></div></td></tr></tbody></table></div></section>
</section>
</template>
<style scoped>
.dashboard-filters{display:flex;gap:12px;align-items:flex-end;margin-bottom:24px;flex-wrap:wrap}.dashboard-filters label{display:flex;flex-direction:column;gap:7px;font-size:1.0625rem;font-weight:600;color:var(--muted)}.dashboard-filters input,.dashboard-filters select{border:1px solid var(--border,#e2e8f0);background:var(--surface,#fff);color:inherit;border-radius:9px;padding:9px 11px;min-height:44px;font:inherit}.dashboard-filters button{min-height:44px}@media(max-width:600px){.dashboard-filters label{flex:1;min-width:120px}.dashboard-filters select{width:100%}}
.participant-dashboard-heading{display:grid;grid-template-columns:auto minmax(0,1fr);column-gap:16px;align-items:center}.dashboard-profile-avatar{grid-column:1;grid-row:1/4;align-self:start;display:inline-flex;border-radius:50%}.participant-dashboard-heading>.eyebrow,.participant-dashboard-heading>h1,.participant-dashboard-heading>p{grid-column:2}@media(max-width:600px){.dashboard-profile-avatar{grid-row:1}.participant-dashboard-heading>h1,.participant-dashboard-heading>p{grid-column:1/-1}.participant-dashboard-heading>.eyebrow{margin:0}}
.dashboard-page{min-width:0}.dashboard-page :is(.page-heading>div,.metric-card,.panel,.package-card,.skill-item>div,.banner-copy){min-width:0}.dashboard-page :is(h1,h2,h3,p,.metric-value,.metric-label,.table-title,.skill-item strong){overflow-wrap:anywhere}.dashboard-page :is(.button,.text-button){white-space:normal;min-height:44px;max-width:100%;line-height:1.5}.dashboard-page .inline-error{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.dashboard-page .inline-error>span{min-width:0;overflow-wrap:anywhere}.dashboard-filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr)) auto;gap:16px;align-items:end;padding:20px;border:1px solid var(--border);border-radius:16px;background:var(--surface)}.dashboard-filters:has(>a){grid-template-columns:repeat(4,minmax(0,1fr)) auto auto}.dashboard-filters label{min-width:0;font-size:1.0625rem;line-height:1.6}.dashboard-filters :is(input,select){min-width:0;width:100%;max-width:100%;min-height:48px;font-size:1.0625rem;color:var(--text);padding:10px 12px}.dashboard-filters>.button{min-height:48px}.metric-grid{align-items:stretch}.metric-value{line-height:1.3;max-width:100%}.metric-value-text{font-size:clamp(1.5rem,2.5vw,2rem)}.skill-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.skill-item{align-items:flex-start;min-width:0}.skill-item>div{flex:1}.skill-item strong{font-size:1.125rem;line-height:1.5}.skill-item small{line-height:1.6;font-size:1rem}.skill-icon{flex-shrink:0}.section-heading,.type-history-heading{flex-wrap:wrap;gap:16px;align-items:flex-start}.section-heading h2{font-size:clamp(1.5rem,2.4vw,1.75rem);line-height:1.4}.section-heading p{font-size:1.125rem;line-height:1.7}.package-grid{align-items:stretch}.package-grid>.package-card{display:flex;flex-direction:column;min-width:0}.package-card h3{font-size:1.375rem;line-height:1.5}.package-card>p{font-size:1.125rem;flex:1;min-height:0}.package-card>.button{margin-top:auto}.package-top,.package-meta{flex-wrap:wrap;gap:12px}.package-grid>.package-card:nth-child(3){display:flex}.activity-panel .panel-heading{gap:16px;flex-wrap:wrap;align-items:flex-start}.activity-panel .panel-heading h3,.proficiency-panel .panel-heading h3{font-size:1.375rem;line-height:1.5}.activity-panel .panel-heading p,.proficiency-panel .panel-heading p{font-size:1.125rem;line-height:1.7}.table-scroll{max-width:100%;overscroll-behavior-x:contain}.table-scroll table{min-width:680px}.table-scroll:focus-visible{outline:3px solid var(--color-accent);outline-offset:3px}
@media(max-width:1366px){.dashboard-filters,.dashboard-filters:has(>a){grid-template-columns:repeat(2,minmax(0,1fr))}.dashboard-filters>.button{justify-self:start}.dashboard-grid{grid-template-columns:minmax(0,1fr)}.skill-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:1024px){.package-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.welcome-banner{padding:28px;min-height:300px}.banner-copy{max-width:65%}.journey-art{width:28%;max-width:260px;right:16px}.skill-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:600px){.dashboard-filters,.dashboard-filters:has(>a){grid-template-columns:minmax(0,1fr);padding:16px;gap:16px}.dashboard-filters label{min-width:0}.dashboard-filters>.button{width:100%;justify-self:stretch}.welcome-banner{padding:24px;min-height:0}.banner-copy{max-width:100%;width:100%}.banner-copy h2{font-size:1.75rem;max-width:none}.banner-copy p{font-size:1.125rem;max-width:none}.journey-art{display:none}.metric-grid{grid-template-columns:minmax(0,1fr);gap:16px}.metric-card{padding:24px}.metric-label,.metric-foot{font-size:1.0625rem}.skill-grid,.package-grid{grid-template-columns:minmax(0,1fr)}.section-heading p{max-width:none}.page-heading{flex-wrap:wrap}.participant-dashboard-heading{row-gap:12px}.activity-panel .panel-heading>.text-button{justify-content:flex-start}.progress-invite{padding:24px}.progress-invite p{font-size:1.125rem;max-width:none}.progress-invite h3{font-size:1.5rem;max-width:none}}
</style>




